async function showReceipt(id){
  try{
    const r=await api('/api/sales/'+id+'/receipt'),v=r.venta;
    const rawType=String(v.tipo_comprobante||'ORDEN').toUpperCase();
    const dc=v.documentos_config||{}; const dk=rawType==='ORDEN'?'orden':rawType==='BOLETA'?'boleta':rawType==='FACTURA'?'factura':rawType.includes('NOTA')?'nota_credito':'cotizacion'; const dcfg=dc[dk]||{}; const vis=documentPrintVisibility(dc);
    const labels={
      'ORDEN':'ORDEN DE VENTA',
      'BOLETA':'BOLETA DE VENTA',
      'FACTURA':'FACTURA',
      'NOTA DE CREDITO':'NOTA DE CRÉDITO',
      'NOTA DE CRÉDITO':'NOTA DE CRÉDITO',
      'COTIZACION':'COTIZACIÓN',
      'COTIZACIÓN':'COTIZACIÓN'
    };
    const docLabel=dcfg.titulo||labels[rawType]||rawType;
    const number=[v.serie,v.numero].filter(Boolean).join('-')||String(v.id).slice(0,8).toUpperCase();
    const dt=new Date(v.created_at).toLocaleString('es-PE',{timeZone:'America/Lima',dateStyle:'short',timeStyle:'short'});
    const isFiscal=['BOLETA','FACTURA','NOTA DE CREDITO','NOTA DE CRÉDITO'].includes(rawType);
    const clientDoc=v.nro_doc?`${rawType==='FACTURA'?'RUC':'DOC.'}: ${esc(v.nro_doc)}`:'SIN DOCUMENTO';
    const rows=r.items.map(i=>`<tr><td class="desc"><b>${esc(i.nombre)}</b><small>${esc(i.presentacion_venta||'UNIDAD')}</small></td><td>${Number(i.cantidad)}</td><td>${money(i.precio_unitario).replace('S/ ','')}</td><td>${money(i.total).replace('S/ ','')}</td></tr>`).join('');
    const pay=(r.pagos||[]).map(x=>`${esc(x.metodo)} ${money(x.monto)}`).join(' · ')||'—';
    $('receiptContent').innerHTML=`<div id="printArea" class="edux-ticket">
      ${printDocumentHeader(v,vis)}
      <div class="ticket-doc"><b>${esc(docLabel)}</b><strong>${esc(number)}</strong>${!isFiscal?'<small>DOCUMENTO INTERNO</small>':''}</div>
      <div class="ticket-client"><b>CLIENTE</b><span>${esc(v.cliente||'Público en general')}</span><span>${clientDoc}</span></div>
      <div class="ticket-meta"><span><b>FECHA:</b> ${esc(dt)}</span><span><b>VENDEDOR:</b> ${esc(v.vendedor||'')}</span></div>
      <table class="ticket-items"><thead><tr><th>DESCRIPCIÓN</th><th>CANT.</th><th>PRECIO</th><th>IMPORTE</th></tr></thead><tbody>${rows}</tbody></table>
      <div class="ticket-totals"><span>SUBTOTAL <b>${money(v.subtotal)}</b></span>${Number(v.descuento||0)>0?`<span>DESCUENTO <b>${money(v.descuento)}</b></span>`:''}<span class="grand">TOTAL <b>${money(v.total)}</b></span></div>
      <div class="ticket-pay"><b>FORMA DE PAGO</b><span>${pay}</span></div>
      ${dcfg.nota?`<p class="ticket-note">${esc(dcfg.nota)}</p>`:''}
      <div class="ticket-footer"><b>${esc(dcfg.pie||v.mensaje_ticket||'Gracias por su compra')}</b><span>EDUXFAC</span></div>
    </div>`;
    // v44.0: prepara 58 mm, 80 mm o A4; CSS de impresión aísla físicamente el comprobante.
    const printWidth=String(v.impresion_ancho_mm||document.getElementById('cfgWidth')?.value||'80');
    document.body.classList.remove('edux-print-58','edux-print-80','edux-print-a4');

