async function confirmReturnSale(){if(!returnSaleData)return;const tipo=$('returnSaleType').value,motivo=$('returnSaleReason').value.trim(),metodo_reembolso=$('returnSaleMethod').value;if(!motivo){await showAppNotice('Indica el motivo.');return}let items=[];if(tipo!=='TOTAL'){const groups=returnGroups(),keys=new Set([...document.querySelectorAll('.return-group:checked')].map(x=>x.dataset.key));for(const g of groups)if(keys.has(g.key))for(const d of g.details)items.push({venta_detalle_id:d.id,cantidad:d.qty});}if(tipo==='PARCIAL'&&!items.length){await showAppNotice('Selecciona al menos un producto para devolver.');return}const msg=tipo==='TOTAL'?'¿Seguro que deseas ANULAR TODA LA VENTA? Se devolverá el stock y se registrará el reembolso.':'¿Confirmas esta devolución parcial? El stock regresará al inventario.';if(!await showAppConfirm(msg))return;try{$('returnSaleConfirm').disabled=true;const r=await api('/api/sales/'+returnSaleData.venta.id+'/return',{method:'POST',body:JSON.stringify({tipo,motivo,metodo_reembolso,items,sesion_caja_id:state.cash?.id||null})});await showAppNotice(`Operación registrada. Reembolso: ${money(r.monto)} · Estado: ${r.estado_venta}`);$('returnSaleModal').classList.add('hidden');$('salesDetailModal').classList.add('hidden');await Promise.allSettled([loadRecentSales(),loadDashboard(),loadCash(),loadReports()])}catch(e){await showAppNotice(e.message)}finally{$('returnSaleConfirm').disabled=false}}

