pdateChrome()}catch(err){$('saleStatus').textContent=err.message;if(['VENTA_SIN_RENTABILIDAD','VENTA_COSTO_NO_VERIFICABLE'].includes(err.code))await window.eduxfacShowSaleProfitability(err)}finally{checkoutPending=false;$('checkout').disabled=false;setTimeout(focusSalesSearchIfReady,0)}}

const money = n => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const numeric = (value, label) => {
  const n = Number(value);
  if (!Number.isFinite(n)) throw new Error(`${label} inválido.`);
  return n;
};

